def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def tau_of_n_to_12(n):
    if n == 1:
        return 1
    factors = prime_factorization(n)
    tau = 1
    for exponent in factors.values():
        tau *= (12 * exponent + 1)
    return tau

# Step 1: Verify n=1
n_test = 1
tau_result = tau_of_n_to_12(n_test)
print(f"n={n_test}: LHS = {n_test}, RHS = tau(n^{12}) = {tau_result}. Match: {n_test == tau_result}")

# Step 2 & 3: Check composite values of n up to 20
composites = [4, 6, 8, 9, 10, 12, 14, 15, 16, 18, 20]
print("\n--- Composite Numbers Check ---")
results = {}
for n in composites:
    tau_result = tau_of_n_to_12(n)
    match = n == tau_result
    results[n] = (n, tau_result, match)
    print(f"n={n}: LHS = {n}, RHS = tau(n^{12}) = {tau_result}. Match: {match}")

# Summarize results
print("\nSummary:")
for n, (lhs, rhs, matched) in results.items():
    if matched:
        print(f"Solution found: n={n}")
    else:
        print(f"Counterexample/No match: n={n} (LHS={lhs} != RHS={rhs})")

