    if n == 1:
        return 1

    # This helper function calculates the required RHS based on prime factorization of n
    # n = p1^a1 * p2^a2 * ...
    # RHS = (12*a1 + 1) * (12*a2 + 1) * ...

    factors = {}
    temp_n = n
    d = 2
    while d * d <= temp_n:
        while temp_n % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp_n //= d
        d += 1
    if temp_n > 1:
        factors[temp_n] = factors.get(temp_n, 0) + 1

    rhs = 1
    for p, a in factors.items():
        rhs *= (12 * a + 1)
    return rhs

